,["380081"]={["key"]="380081",["language1"]=[[<color=#ffc146>【简介】</color>
「数据复录」为「虚数天灾」内的扫荡功能。

<color=#ffc146>【功能说明】</color>
1.总队长需先出战记录所战斗的阵容、伤害和奖励。
2.记录成功后即可使用该记录进行关卡扫荡，直接获得对应奖励。
3.扫荡也需要花费入场道具。
4.扫荡也遵循角色每日出战次数限制。
5.每个关卡最多3个记录，满时只能替换其中任意一个。被删除或替换的记录无法复原。]],["id"]="380081",["language4"]="none",["language3"]="none",["language2"]=[[<color=#ffc146>【簡介】</color>
「數據複錄」為「虛數天災」內的掃蕩功能。

<color=#ffc146>【功能說明】</color>
1.總隊長需先出戰記錄所戰鬥的陣容、傷害和獎勵。
2.記錄成功後即可使用該記錄進行關卡掃蕩，直接獲得對應獎勵。
3.掃蕩也需要花費入場道具。
4.掃蕩也遵循角色每日出戰次數限制。
5.每個關卡最多3個記錄，滿時只能替換其中任意一個。被刪除或替換的記錄無法復原。]]}
