,["380054"]={["key"]="380054",["language1"]=[[<color=#ffc146>【简介】</color>
「虚数天灾」是全服讨伐boss的活动。

<color=#ffc146>【玩法说明】</color>
1.活动期间，通过完成任务即可获得入场道具，每次挑战均需要一个入场道具（模拟不消耗）。
2.「虚数天灾」共分为「解构战」和「核心战」两个阶段。「解构战」中挑战部位，需要击败所有部位才能进入「核心战」。「核心战」中挑战最终boss，可根据选择的boss增益获得奖励加成。
3.根据总队长在战斗中造成的伤害，根据一定比例转化获得奖励道具。可使用奖励道具在<color=#ffc146>补给哨站</color>中兑换奖励。
4.「虚数天灾」中的怪物血量进度全服共享，血量进度刷新有延迟。
5.「虚数天灾」中的角色<color=#ffc146>每日只能出战一次</color>，每日3点刷新出战次数。]],["id"]="380054",["language4"]="none",["language3"]="none",["language2"]=[[<color=#ffc146>【簡介】</color>
「虛數天災」是全服討伐boss的活動。

<color=#ffc146>【玩法說明】</color>
1.活動期間，通過完成任務即可獲得入場道具，每次挑戰均需要一個入場道具（模擬不消耗）。
2.「虛數天災」共分為「解構戰」和「核心戰」兩個階段。「解構戰」中挑戰部位，需要擊敗所有部位才能進入「核心戰」。「核心戰」中挑戰最終boss，可根據選擇的boss增益獲得獎勵加成。
3.根據總隊長在戰鬥中造成的傷害，根據一定比例轉化獲得獎勵道具。可使用獎勵道具在<color=#ffc146>補給哨站</color>中兌換獎勵。
4.「虛數天災」中的怪物血量進度全服共用，血量進度刷新有延遲。
5.「虛數天災」中的角色<color=#ffc146>每日只能出戰一次</color>，每日3點刷新出戰次數。]]}
