,["17206"]={["key"]="17206",["language1"]="在<color=#ffae00>【闪亮主唱】</color>构建中构建获取<color=#FF3300>6星</color>角色的基础概率为<color=#ffae00>2%</color>，综合概率为<color=#ffae00>3%（含保底)</color>，<color=#FFCC00>5星</color>队员的基础概率为<color=#ffae00>8%</color>，<color=#6666FF>4星</color>队员的基础概率为<color=#ffae00>40%</color>，<color=#33CCFF>3星</color>队员的基础概率为<color=#ffae00>50%</color>。<color=#ffae00>10连构建必得5星或以上队员</color>。最多<color=#ffae00>50次构建</color>必定能获得保底<color=#ffae00>获取6星角色</color>。",["id"]="17206",["language3"]=[[<color=#ffae00>【シャイニングスター】</color>の中で<color=#FF3300>☆6</color>キャラの基本出現率は<color=#ffae00>2%</color>。<color=#FFCC00>☆5</color>キャラの基本出現率は<color=#ffae00>8%</color>。<color=#6666FF>☆4</color>キャラの基本出現率は<color=#ffae00>40%</color>。<color=#33CCFF>☆3</color>キャラの基本出現率は<color=#ffae00>50%</color>。10連召集は<color=#FFCC00>☆5</color>キャラが1体確定します。
<color=#ffae00>最大50回</color>召集で<color=#FF3300>☆6</color>キャラが確定します。]],["language2"]="在<color=#ffae00>【閃亮主唱】</color>構建中構建獲取<color=#FF3300>6星</color>角色的基礎機率為<color=#ffae00>2%</color>，綜合機率為<color=#ffae00>3%（含保底)</color>，<color=#FFCC00>5星</color>隊員的基礎機率為<color=#ffae00>8%</color>，<color=#6666FF>4星</color>隊員的基礎機率為<color=#ffae00>40%</color>，<color=#33CCFF>3星</color>隊員的基礎機率為<color=#ffae00>50%</color>。<color=#ffae00>10連構建必得5星或以上隊員</color>。最多<color=#ffae00>50次構建</color>必定能獲得保底<color=#ffae00>獲取6星角色</color>。"}
,["17197"]={["key"]="17197",["language1"]="在<color=#ffae00>【猩红猎手】</color>构建中，没有获得6星队员时，都会<color=#ffae00>累积次数</color>，该<color=#ffae00>次数不会因为【猩红猎手】构建的结束而清零</color>，也会应用于接下来任意一次【联动构建】。",["id"]="17197",["language3"]="<color=#ffae00>【血濡れの狩人】</color>の中で、☆6キャラを獲得しなかった場合、召集を行った回数が<color=#ffae00>カウントされます</color>。<color=#ffae00>カウントは【血濡れの狩人】の終了によってリセットされることはありません</color>。次の【コラボ召集】に引き継がれます。",["language2"]="在<color=#ffae00>【猩紅獵手】</color>構建中，沒有獲得6星隊員時，都會<color=#ffae00>累積次數</color>，該<color=#ffae00>次數不會因為【猩紅獵手】構建的結束而清零</color>，也會應用於接下來任意一次【聯動構建】。"}
