,["17172"]={["key"]="17172",["language1"]="在所有<color=#9a80b7>【自选构建】</color>中构建获取<color=#FF3300>6星</color>队员的基础概率为<color=#ffae00>2.2%</color>，综合获取概率为<color=#ffae00>3%</color>（含出率上升），<color=#FFCC00>5星</color>队员的基础概率为<color=#ffae00>8%</color>，<color=#6666FF>4星</color>队员的基础概率为<color=#ffae00>40%</color>，<color=#33CCFF>3星</color>队员的基础概率为<color=#ffae00>49.8%</color>。10连构建必得<color=#FFCC00>5星</color>或以上队员。如果连续50次没有获得<color=#FF3300>6星</color>队员，则下一次获得<color=#FF3300>6星</color>队员的概率将从原本的<color=#ffae00>2.2%</color>提升至<color=#ffae00>4.2%</color>。如果该次还没有获得<color=#FF3300>6星</color>队员，则下一次构建获得<color=#FF3300>6星</color>队员的概率由<color=#ffae00>4.2%</color>提升到<color=#ffae00>6.2%</color>。直至达到<color=#ffae00>100%</color>时必定获得<color=#FF3300>6星</color>队员",["id"]="17172",["language2"]="在所有<color=#9a80b7>【自選構建】</color>中構建獲取<color=#FF3300>6星</color>隊員的基礎概率為<color=#ffae00>2.2%</color>，綜合獲取概率為<color=#ffae00>3%</color>（含出率上升），<color=#FFCC00>5星</color>隊員的基礎概率為<color=#ffae00>8%</color>，<color=#6666FF>4星</color>隊員的基礎概率為<color=#ffae00>40%</color>，<color=#33CCFF>3星</color>隊員的基礎概率為<color=#ffae00>49.8%</color>。10連構建必得<color=#FFCC00>5星</color>或以上隊員。如果連續50次沒有獲得<color=#FF3300>6星</color>隊員，則下一次獲得<color=#FF3300>6星</color>隊員的概率將從原本的<color=#ffae00>2.2%</color>提升至<color=#ffae00>4.2%</color>。如果該次還沒有獲得<color=#FF3300>6星</color>隊員，則下一次構建獲得<color=#FF3300>6星</color>隊員的概率由<color=#ffae00>4.2%</color>提升到<color=#ffae00>6.2%</color>。直至達到<color=#ffae00>100%</color>時必定獲得<color=#FF3300>6星</color>隊員"}
