,["13023"]={["key"]="13023",["language1"]=[[1.参与过活动的总队长可以在赛程完成后的次日签到时获得最终奖励“香甜软糯”或“油润鲜香”。奖励款式将会根据总队长的口味倾向决定。
2.为香甜软糯队加油次数多的总队长会获得最终奖励：<color="#ffc146">香甜软糯</color>头像与称号。
3.为油润鲜香队加油次数多的总队长会获得最终奖励：<color="#ffc146">油润鲜香</color>头像与称号。
4.为双方队伍加油数相同的总队长将会加入好吃就行队，好吃就行队会获得胜利方阵营的最终奖励
5.<color="#ffc146">若总队长在加油活动期间内未进行过加油，则加油活动结束后无法获得阵营奖励</color>]],["id"]="13023",["language3"]=[[1.イベントに参加した総隊長は、レース終了後の翌日のログイン時にイベント最終報酬「甘くもちもち」または「辛くパリパリ」を受け取ることができます。報酬の種類は総隊長の好みによって決まります。
2.甘くもちもちチームを応援した回数が多い総隊長は、最終報酬：<color="#ffc146">甘くもちもち</color>のアイコンと称号を獲得します。
3.辛くパリパリチームを応援した回数が多い総隊長は、最終報酬：<color="#ffc146">辛くパリパリ</color>のアイコンと称号を獲得します。
4.両チームを応援した回数が同じ総隊長は、おいしければいいチームに参加し、おいしければいいチームは勝利陣営の最終報酬を獲得します。
5.<color="#ffc146">総隊長が応援イベント期間中に応援を行わなかった場合、応援イベント終了後に陣営報酬を獲得することはできません</color>]],["language2"]=[[1.參與過活動的總隊長可以在賽程完成後的次日簽到時獲得最終獎勵“香甜軟糯”或“油潤鮮香”。獎勵款式將會根據總隊長的口味傾向決定。
2.為香甜軟糯隊加油次數多的總隊長會獲得最終獎勵：<color="#ffc146">香甜軟糯</color>頭像與稱號。
3.為油潤鮮香隊加油次數多的總隊長會獲得最終獎勵：<color="#ffc146">油潤鮮香</color>頭像與稱號。
4.為雙方隊伍加油數相同的總隊長將會加入好吃就行隊，好吃就行隊會獲得勝利方陣營的最終獎勵
5.<color="#ffc146">若總隊長在加油活動期間內未進行過加油，則加油活動結束後無法獲得陣營獎勵</color>]]}
