,["340017"]={["key"]="340017",["language1"]=[[<color=#ffc146>【简介】</color>
「潜能拓展」 可以提升队员的能力属性及技能效果，能大幅提升队员的战斗能力。

<color=#ffc146>【说明】</color>
1.当队员达到80级，且已开放潜能拓展系统，则会在角色界面右下方出现系统入口。
2.通过消耗通用潜能拓展升级道具可提升潜能等级，在特殊节点需要使用队员专用的潜能升级道具，与之对应的是升级可获得更强的属性或技能。
3.队员会在潜能拓展至4级时获得额外技能能力，且在满级10级时，额外技能能力会进一步升级。
4.潜能拓展会在后续版本逐步为队员开放。]],["id"]="340017",["language3"]="none",["language2"]=[[<color=#ffc146>【簡介】</color>
「潛能拓展」 可以提升隊員的能力屬性及技能效果，能大幅提升隊員的戰鬥能力。

<color=#ffc146>【說明】</color>
1.當隊員達到80級，且已開放潛能拓展系統，則會在角色介面右下方出現系統入口。
2.通過消耗通用潛能拓展升級道具可提升潛能等級，在特殊節點需要使用隊員專用的潛能升級道具，與之對應的是升級可獲得更強的屬性或技能。
3.隊員會在潛能拓展至4級時獲得額外技能能力，且在滿級10級時，額外技能能力會進一步升級。
4.潛能拓展會在後續版本逐步為隊員開放。]]}
