,["320024"]={["key"]="320024",["language1"]=[[<color=#ffc146>【简介】</color>
「时尚典籍」 是通过任务获取典籍经验，升级典籍获得奖励的活动。

<color=#ffc146>【活动说明】</color>
1.通过完成任务获得典籍经验升级典籍，到达等级即可获得奖励并且挑战关卡。解锁高级典籍可获得更多奖励！
2.<color=#ffc146>额外奖励需要通关对应等级关卡才能领取。</color>
3.关卡分为时装挑战和荣誉挑战：时装挑战仅可使用预设队伍，首通胜利后可获得奖励；荣誉挑战首通胜利后可获得称号。
4.时装关卡首通并且解锁高级典籍，即可获得时装奖励！
5.时尚典籍内的典籍经验不共享，均为独立计算。
]],["id"]="320024",["language3"]="None",["language2"]=[[<color=#ffc146>【簡介】</color>
「時尚典籍」 是通過任務獲取典籍經驗，升級典籍獲得獎勵的活動。

<color=#ffc146>【活動說明】</color>
1.通過完成任務獲得典籍經驗升級典籍，到達等級即可獲得獎勵並且挑戰關卡。解鎖高級典籍可獲得更多獎勵！
2.<color=#ffc146>額外獎勵需要通關對應等級關卡才能領取。</color>
3.關卡分為時裝挑戰和榮譽挑戰：時裝挑戰僅可使用預設隊伍，首通勝利後可獲得獎勵；榮譽挑戰首通勝利後可獲得稱號。
4.時裝關卡首通並且解鎖高級典籍，即可獲得時裝獎勵！
5.時尚典籍內的典籍經驗不共用，均為獨立計算。
]]}
