,["312023"]={["key"]="312023",["language1"]=[[<color=#ffc146>【简介】</color>
「永境战域」是通过不断挑战层数，获得奖励的常驻玩法。

<color=#ffc146>【规则说明】</color>
1.在永境战域中，角色与怪物的血量将会继承。操作数上限或血量归0的角色将会退场，在周期刷新前无法再出战。
2.每周一的3:00会重置所有角色的出战状态和血量，玩家也可以使用指定道具重置所有角色的出战状态和血量（怪物的血量和层数进度不会刷新）。
3.仅当层怪物阵亡时才能进入下一层。
<color=#ffc146>【奖励说明】</color>
分为首通奖励和累计层数奖励，均只能领取一次。
<color=#ffc146>【排行榜奖励】</color>
1.永境战域玩法中，<color=#ffc146>前50位</color>通关50层的玩家，将会获得<color=#ffc146>绝版头像</color>奖励！
2.通关50层的玩家可获得<color=#ffc146>头像奖励</color>！
3.奖励邮件发放有延迟，注意查收。]],["id"]="312023",["language3"]="None",["language2"]=[[<color=#ffc146>【簡介】</color>
「永境戰域」是通過不斷挑戰層數，獲得獎勵的常駐玩法。

<color=#ffc146>【規則說明】</color>
1.在永境戰域中，角色與怪物的血量將會繼承。操作數上限或血量歸0的角色將會退場，在週期刷新前無法再出戰。
2.每週一的3:00會重置所有角色的出戰狀態和血量，玩家也可以使用指定道具重置所有角色的出戰狀態和血量（怪物的血量和層數進度不會刷新）。
3.僅當層怪物陣亡時才能進入下一層。
<color=#ffc146>【獎勵說明】</color>
分為首通獎勵和累計層數獎勵，均只能領取一次。
<color=#ffc146>【排行榜獎勵】</color>
1.永境戰域玩法中，<color=#ffc146>前100位</color>通關50層的玩家，將會獲得<color=#ffc146>絕版頭像</color>獎勵！
2.通關50層的玩家可獲得<color=#ffc146>頭像獎勵</color>！
3.獎勵郵件發放有延遲，注意查收。]]}
