,["190209"]={["key"]="190209",["language1"]=[[<color=#ffc146>【活动简介】</color>
活动期间，可消耗幸运凭证参与抽奖，有机会获得时装、养成材料等游戏内奖励。

<color=#ffc146>【抽奖规则】</color>
1.幸运凭证可通过粲晶购买或直购获得。
2.每次抽奖需消耗一定数量的幸运凭证，具体消耗数量为：第1次至第10次抽取依次消耗0、1、1、2、4、4、5、5、6、6张幸运凭证，全部抽取合计消耗34张。
3.每次抽奖必定获得1个奖励，已获得的奖励不会重复获得。
4.每次抽取后，已获得的奖励将从奖池中移除，后续抽取将在剩余奖励中进行。
5.奖池内容会随抽取进度逐步开放，S级奖励将于第5次抽取起开放获取。
6.获得S级奖励后，本轮奖池抽取即完成，无法继续进行抽取。
7.活动结束后，购买后且未使用的幸运凭证将按规则自动转换为粲晶。

<color=#ffc146>【奖励内容】</color>
S级奖励：时装
A级奖励：构建蓝图3、数据协议50、重构凝剂4、T4跃升选择箱1、武装技能训练III*3
B级奖励：燃料120、破碎程式100、初级调频增幅仪10、R4升级芯片2

<color=#ffc146>【概率信息】</color>
本活动概率将根据奖池内当前可抽取的奖励内容进行计算。
S级奖励权重：360
A级，B级奖励各项权重：1071
S级奖励将于第5次抽取起开放获取。]],["id"]="190209",["language3"]=[[<color=#ffc146>【イベント概要】</color>
イベント期間中、幸運の証を消費して抽選に参加すると、スキンや育成素材などのゲーム内報酬を獲得するチャンスがあります。

<color=#ffc146>【抽選ルール】</color>
1.幸運の証は輝晶で購入するか、直接購入で獲得できます。
2.抽選1回ごとに一定数の幸運の証を消費します。必要数は以下の通りです：1回目から10回目まで順に0、1、1、2、4、4、5、5、6、6枚の幸運の証を消費し、全て引くと合計34枚消費します。
3.抽選1回ごとに必ず1つの報酬を獲得でき、獲得済みの報酬は重複して獲得しません。
4.抽選後、獲得済みの報酬は報酬プールから除外され、以降の抽選は残りの報酬から行われます。
5.報酬プールの内容は抽選の進行に応じて順次開放され、S級報酬は5回目の抽選から獲得可能になります。
6.S級報酬を獲得すると、このラウンドの報酬プール抽選は完了となり、以降は抽選できません。
7.イベント終了後、購入済みかつ未使用の幸運の証は、ルールに従って自動的に輝晶へ変換されます。

<color=#ffc146>【報酬内容】</color>
S級報酬：スキン
A级報酬：召集券×3、プロトコルチップ×50、再構成凝化剤×4、T4昇格選択BOX×1、武装スキル訓練III×3
B級報酬：燃料×120、データ破片×100、初級調律増幅儀×10、R4LvUPチップ×2

<color=#ffc146>【確率情報】</color>
本イベントの確率は、報酬プール内で現在抽選可能な報酬内容に応じて計算されます。
S級報酬のウェイト：360
A级、B級報酬の各ウェイト：1071
S級報酬は5回目の抽選から開放されます]],["language2"]=[[<color=#ffc146>【活動簡介】</color>
活動期間，可消耗幸運憑證參與抽獎，有機會獲得時裝、養成材料等遊戲內獎勵。

<color=#ffc146>【抽獎規則】</color>
1.幸運憑證可通過粲晶購買或直購獲得。
2.每次抽獎需消耗一定數量的幸運憑證，具體消耗數量為：第1次至第10次抽取依次消耗0、1、1、2、4、4、5、5、6、6張幸運憑證，全部抽取合計消耗34張。
3.每次抽獎必定獲得1個獎勵，已獲得的獎勵不會重複獲得。
4.每次抽取後，已獲得的獎勵將從獎池中移除，後續抽取將在剩餘獎勵中進行。
5.獎池內容會隨抽取進度逐步開放，S級獎勵將於第5次抽取起開放獲取。
6.獲得S級獎勵後，本輪獎池抽取即完成，無法繼續進行抽取。
7.活動結束後，購買後且未使用的幸運憑證將按規則自動轉換為粲晶。

<color=#ffc146>【獎勵內容】</color>
S級獎勵：時裝
A級獎勵：構建藍圖3、數據協議50、重構凝劑4、T4躍升選擇箱1、武裝技能訓練III*3
B級獎勵：燃料120、破碎程式100、初級調頻增幅儀10、R4升級晶片2

<color=#ffc146>【概率資訊】</color>
本活動概率將根據獎池內當前可抽取的獎勵內容進行計算。
S級獎勵權重：360
A級，B級獎勵各項權重：1071
S級獎勵將於第5次抽取起開放獲取。]]}
