,["180009"]={["key"]="180009",["language1"]=[[<color=#ffc146>【简介】</color>
「次元馈赠」 是推出的限时福利活动，在活动期间内进行构建即有概率免费获得周边实物奖励<color=#ffc146>纪念画册，炫彩色纸，绚丽吧唧</color>。

<color=#ffc146>【规则说明】</color>
1.活动开启后，进行构建即有概率获得周边实物奖励
2.奖励数量有限，送完即止！剩余数量将显示在次元馈赠活动界面中，数量刷新可能存在延迟。
3.参与新手「特装构建」时不会获得周边实物奖励。
4.若获得奖励，在关闭构建结果后将展示获得的奖励内容
<color=#ffc146>【奖励发放说明】</color>
1.获得奖励后，请前往背包中查看并使用【识别码容器】道具，获得领奖兑换码，请妥善保管兑换码。
2.在活动期间内，前往官方淘宝店铺，提供<color=#ffc146>兑换码和UID</color>即可兑换对应奖励，请及时前往兑换。
3.其中色纸和徽章将在兑换时随机获得任意一款。]],["id"]="180009",["language3"]="NONE",["language2"]=[[「次元饋贈」 是推出的限時福利活動，在活動期間內進行構建即有機率免費獲得周邊實物獎勵<color=#ffc146>紀念畫冊、壓克力大立牌、胸部滑鼠墊、等身大抱枕</color>。

<color=#ffc146>【規則說明】</color>
1.活動開啟後，進行構建即有機率獲得周邊實物獎勵
2.獎勵數量有限，送完即止！剩餘數量將顯示在次元饋贈活動介面中，數量刷新可能存在延遲。
3.參與新手「特裝構建」時不會獲得周邊實物獎勵。
4.若獲得獎勵，在關閉構建結果後將展示獲得的獎勵內容
<color=#ffc146>【獎勵發放說明】</color>
1.獲得獎勵後，請前往背包中查看並使用【識別碼容器】道具，獲得領獎兌換碼，請妥善保管兌換碼。
2.在活動期間內，前往FaceBook官方粉絲團置頂表單登記，登記期限至2月19日23:59結束，請及時前往兌換。
3.若獎品有不同款式將隨機獲得一款。]]}
