,["17175"]={["key"]="17175",["language1"]="【<color=#ffae00>注意</color>】本构建属于<color=#9a80b7>【自选构建】</color>，其构建次数会一直累计于<color=#9a80b7>【自选构建】</color>中，与其他类型的构建次数保底相互独立计算，互不影响。",["id"]="17175",["language2"]="【<color=#ffae00>注意</color>】本構建屬於<color=#9a80b7>【自選構建】</color>，其構建次數會一直累計於<color=#9a80b7>【自選構建】</color>中，與其他類型的構建次數保底相互獨立計算，互不影響。"}
