,["4102"]={["key"]="4102",["language1"]="主体角色同步率到达100时，可以与特定目标同调，获得全新技能，同调后立即获得行动并恢复100同步率；当同步率耗尽后解除同调，自身和参与对象都虚弱1回合",["id"]="4102",["language3"]="キャラのSPが100になった時、特定の対象と同調できるようになる。同調後、スキルが一新される。そして直ちに行動可能となり、100SPが回復する。SPがすべて消費された場合は、同調状態を解除して、自身と同調対象が1ターンの間に過熱状態になる。",["language2"]="主體角色同步率到達100時，可以與特定目標同調，獲得全新技能，同調後立即獲得行動並恢復100同步率；當同步率耗盡後解除同調，自身和參與對象都虛弱1回合"}
