,["47014"]={["key"]="47014",["language1"]=[[<color=#ffc146>【简介】</color>
完成对应的成就任务，即可领取对应的奖励。

<color=#ffc146>【规则】</color>
1.部分成就会默认隐藏，需要完成它的前置成就后才能显示出来。
2.成就中包含稀有的隐藏成就，隐藏成就并不会直接显示条件且进度会以？？的方式显示，直到玩家完成后才会正常显示]],["id"]="47014",["language2"]=[[<color=#ffc146>【簡介】</color>
完成對應的成就任務，即可領取對應的獎勵。

<color=#ffc146>【規則】</color>
1.部分成就會默認隱藏，需要完成它的前置成就後才能顯示出來。
2.成就中包含稀有的隱藏成就，隱藏成就並不會直接顯示條件且進度會以？？的方式顯示，直到玩家完成後才會正常顯示]]}
