,["15098"]={["key"]="15098",["language1"]=[[1、提示有<color=#FFC142>类型掉落加成的副本</color>会共享掉落加成次数消耗。
2、开启掉落加成后，挑战副本成功时掉落的物品数量会增加。
3、掉落加成次数会在每日凌晨3点重置。]],["id"]="15098",["language3"]=[[1．<color=#FFC142>同種類のクエスト</color>におけるドロップボーナス回数が共通である。
2．ドロップボーナス使用後、クエストに挑戦成功する際にドロップするアイテム数が増加する。
．ドロップボーナス回数は毎日4時に更新される。]],["language2"]=[[1、提示有<color=#FFC142>類型掉落加成的副本</color>會共用掉落加成次數消耗。
2、開啟掉落加成後，挑戰副本成功時掉落的物品數量會增加。
3、掉落加成次數會在每日淩晨3點重置。]]}
,["17199"]={["key"]="17199",["language1"]="在所有<color=#ffae00>【定制构建ε】</color>中构建获取<color=#FF3300>6星</color>角色的基础概率为<color=#ffae00>2%</color>，综合概率为<color=#ffae00>3%（含保底)</color>，<color=#FFCC00>5星</color>队员的基础概率为<color=#ffae00>8%</color>，<color=#6666FF>4星</color>队员的基础概率为<color=#ffae00>40%</color>，<color=#33CCFF>3星</color>队员的基础概率为<color=#ffae00>50%</color>。10连构建必得<color=#FFCC00>5星</color>或以上队员。最多50次构建必定能获得保底获取<color=#FF3300>6星</color>角色。",["id"]="17199",["language2"]="在所有<color=#ffae00>【定制構建ε】</color>中構建獲取<color=#FF3300>6星</color>角色的基礎機率為<color=#ffae00>2%</color>，綜合概率為<color=#ffae00>3%（含保底)</color>，<color=#FFCC00>5星</color>隊員的基礎機率為<color=#ffae00>8%</color>，<color=#6666FF>4星</color>隊員的基礎機率為<color=#ffae00>40%</color>，<color=#33CCFF>3星</color>隊員的基礎機率為<color=#ffae00>50%</color>。10連構建必得<color=#FFCC00>5星</color>或以上隊員。最多50次構建必定能獲得保底獲取<color=#FF3300>6星</color>角色。"}
