,["311014"]={["key"]="311014",["language1"]=[[新途补给：
1.新途补给可通过小额多次（每天可购买1次）的付费，获得超性价比的粲晶补给。
2.总队长可在激活截止时间前即10月27日前，付费激活新途补给。
3.若在10月27日前未激活新途补给，则活动结束，活动入口隐藏。
4.激活后，会即刻获得粲晶，且后续可多日付费购买高性价比粲晶。激活新途补给后，新途补给活动会延长至11月7日凌晨3点。]],["id"]="311014",["language3"]="None",["language2"]=[[新途補給：
1.新途補給可通過小額多次（每天可購買1次）的付費，獲得超性價比的粲晶補給。
2.總隊長可在啟動截止時間前即10月27日前，付費啟動新途補給。
3.若在10月27日前未啟動新途補給，則活動結束，活動入口隱藏。
4.啟動後，會即刻獲得粲晶，且後續可多日付費購買高性價比粲晶。啟動新途補給後，新途補給活動會延長至11月7日淩晨3點。]]}
