,["17120"]={["key"]="17120",["language1"]="【<color=#ffae00>注意</color>】本构建属于【特装构建】，其构建次数保底会一直累计于【特装构建】中，与其他类型的构建次数保底相互独立计算，互不影响。",["id"]="17120",["language3"]="【<color=#ffae00>注意</color>】本構築は【スタートダッシュ構築】に属します。確定までのカウントは別種類の構築とは互いに独立しており、共通しません。",["language2"]="【<color=#ffae00>注意</color>】本構建屬於【特裝構建】，其構建次數保底會一直累計於【特裝構建】中，與其他類型的構建次數保底相互獨立計算，互不影響。"}
