,["100044"]={["key"]="100044",["language1"]=[[1.在对应角色解锁了光环升级系统后，可通过光环旁边的提升按钮进入光环升级界面。
2.光环升级需要消耗指定的增幅仪，等级提升后需要更稀有的增幅仪。
3.光环升级后可解锁不同能力：增加角色自身属性/解锁额外光环阵位/增加额外光环属性/提升光环属性。
4.光环升级系统会随版本逐步为各角色开放。]],["id"]="100044",["language3"]="none",["language2"]=[[1.在對應角色解鎖了光環升級系統後，可通過光環旁邊的提升按鈕進入光環升級介面。
2.光環升級需要消耗指定的增幅儀，等級提升後需要更稀有的增幅儀。
3.光環升級後可解鎖不同能力：增加角色自身屬性/解鎖額外光環陣位/增加額外光環屬性/提升光環屬性。
4.光環升級系統會隨版本逐步為各角色開放。]]}
