,["37055"]={["key"]="37055",["language1"]=[[<color=#ffc146>【简介】</color>
通过选择词条进入战斗，获取积分。

<color=#ffc146>【规则】</color>
1.挑战不消耗燃料，不限制次数。
2.战斗胜利才能获得积分，战斗失败或中途退出无积分。]],["id"]="37055",["language2"]=[[<color=#ffc146>【簡介】</color>
通過選擇詞條進入戰鬥，獲取評分。

<color=#ffc146>【規則】</color>
1.挑戰不消耗燃料與限制次數。
2.戰鬥勝利才能獲得評分，戰鬥失敗無評分。]]}
