,["17007"]={["key"]="17007",["language1"]=[[概率因为存在四舍五入保留两位小数点，所以存在合计无法达到100%的情况

构建时，获得相同角色的情况是存在的

构建时，首先按照品质提供的概率进行抽取，再根据品质中的概率抽取]],["id"]="17007",["language3"]=[[表示されている提供割合は表示上小数点第一位を四捨五入したため、すべて合算しても100％にならない場合があります

構築時、同じキャラを獲得する場合があります

構築時、まずはレアリティの抽選を行います。レアリティが確定した後、キャラクターの抽選を行います]],["language2"]=[[機率因為存在四捨五入保留兩位小數點，所以存在合計無法達到100%的情況

構建時，獲得相同角色的情況是存在的

構建時，首先按照品質提供的機率進行抽取，再根據品質中的機率抽取]]}
