,["17117"]={["key"]="17117",["language1"]=[[第2次至第9次：获取相同<color=#33CCFF>3星</color>角色时，每次将转化为对应角色的<color=#ffae00>「星源」*1</color>和<color=#ffae00>「罕见星尘券」*5</color>。
第10次及之后获取相同角色：将转化为对应角色的<color=#ffae00>「星源」*1</color>和<color=#ffae00>「罕见星尘券」*5</color>。]],["id"]="17117",["language3"]=[[2回目から9回目まで：重複した<color=#FF3300>★3</color>キャラを1体獲得するにつき、そのキャラ専用の<color=#ffae00>「星源」x1</color>と<color=#ffae00>「レア星塵券」x5</color>を獲得する。
10回目以降：そのキャラ専用の<color=#ffae00>「星源」x1</color>と<color=#ffae00>「レア星塵券」x5</color>を獲得する。]],["language2"]=[[第2次至第9次：獲取相同<color=#33CCFF>3星</color>角色時，每次將轉化為對應角色的<color=#ffae00>「星源」*1</color>和<color=#ffae00>「罕見星塵券」*5</color>。
第10次及之後獲取相同角色：將轉化為對應角色的<color=#ffae00>「星源」*1</color>和<color=#ffae00>「罕見星塵券」*5</color>。]]}
