,["90051"]={["key"]="90051",["language1"]=[[限时军演玩法：
1.在指定时间内，限时军演玩法入口开启，在对应时间内，可参与玩家与玩家之间的实时军演。每天有参加次数限制，次数不可额外获得。
2.不同的玩家之间，会根据基础积分进行匹配，会尽可能匹配到当前实力较为接近的玩家进行实时军演。
3.必须配备三支队伍才可参加限时军演，要想获得军演胜利，最好以三支满编队伍进行军演匹配！
4.实时军演结束后，会根据胜负发放“实战徽章”，该道具可在商店内进行商品购买；无论胜负均可获得徽章，胜利一方会根据段位获得额外的徽章奖励！
5.在普遍段位下，实时军演的失败不会扣除积分，指挥官们可以放心进行限时军演；仅有段位达到“中将”及以上的指挥官，在失败中会扣除少量积分。
6.在每一期实时军演中，玩家每一次达到新的段位，都能获得对应段位设定的徽章奖励，而在赛季结束时，总部还会额外奖励排名靠前的若干玩家，因此鼓励指挥官积极冲击更好名次！
7.在每次赛季更新时，总部会收集所有指挥官数据，将使用率最高的队员进行禁用，以考验指挥官们更灵活的编队配置；每期禁用角色不重复，因此不必担心队员无上场机会。
8.在战斗中若选择放弃，则视为认输；若在战斗中离线，则在回合倒计时结束后，玩家会进入自动操作模式。<color=#ffc146>
9.限时军演中，对战双方在进入战斗时会获得额外buff，且随着战斗操作数的增多，会逐渐获得增强buff。在不同段位之间，生效buff在数值上有所不同。</color>]],["id"]="90051",["language2"]=[[限時軍演玩法：
1.在指定時間內，限時軍演玩法入口開啟，在對應時間內，可參與玩家與玩家之間的即時軍演。每天有參加次數限制，次數不可額外獲得。
2.不同的玩家之間，會根據基礎積分進行匹配，會盡可能匹配到當前實力較為接近的玩家進行即時軍演。
3.必須配備三支隊伍才可參加限時軍演，要想獲得軍演勝利，最好以三支滿編隊伍進行軍演匹配！
4.即時軍演結束後，會根據勝負發放“實戰徽章”，該道具可在商店內進行商品購買；無論勝負均可獲得徽章，勝利一方會根據段位獲得額外的徽章獎勵！
5.在普遍段位下，即時軍演的失敗不會扣除積分，指揮官們可以放心進行限時軍演；僅有段位達到“中將”及以上的指揮官，在失敗中會扣除少量積分。
6.在每一期即時軍演中，玩家每一次達到新的段位，都能獲得對應段位設定的徽章獎勵，而在賽季結束時，總部還會額外獎勵排名靠前的若干玩家，因此鼓勵指揮官積極衝擊更好名次！
7.在每次賽季更新時，總部會收集所有指揮官數據，將使用率最高的隊員進行禁用，以考驗指揮官們更靈活的編隊配置；每期禁用角色不重複，因此不必擔心隊員無上場機會。
8.在戰鬥中若選擇放棄，則視為認輸；若在戰鬥中離線，則在回合倒計時結束後，玩家會進入自動操作模式。<color=#ffc146>
9.限時軍演中，對戰雙方在進入戰鬥時會獲得額外buff，且隨著戰鬥操作數的增多，會逐漸獲得增強buff。在不同段位之間，生效buff在數值上有所不同。</color>]]}
