,["17170"]={["key"]="17170",["language1"]="在<color=#ffae00>任何一个【限定构建】</color>中，没有获得6星队员时，都会<color=#ffae00>累积次数</color>，该<color=#ffae00>次数不会因为【限定构建】的结束而清零</color>，也会应用于接下来任意一次【限定构建】",["id"]="17170",["language3"]="<color=#ffae00>任意の【定期構築】</color>の中で、★6キャラを獲得しなかった場合、構築を行った回数が<color=#ffae00>カウントされます</color>。<color=#ffae00>カウントは【定期構築】の終了によってリセットされることはありません</color>。次の【定期構築】に引き継がれます。",["language2"]="在<color=#ffae00>任何一個【限定構建】</color>中，沒有獲得6星隊員時，都會<color=#ffae00>累積次數</color>，該<color=#ffae00>次數不會因為【限定構建】的結束而清零</color>，也會應用於接下來任意一次【限定構建】"}
