,["90037"]={["key"]="90037",["language1"]=[[段位继承规则
所有玩家的段位会重置到上赛季的段位的前2个段位，如上赛季为第8段，本赛季初始为第6段。
同时，本赛季的初始分也会重置到对应段位的基本分。]],["id"]="90037",["language2"]=[[段位繼承規則
所有玩家的段位會重置到上賽季的段位的前2個段位，如上賽季為第8段，本賽季初始為第6段。
同時，本賽季的初始分也會重置到對應段位的基本分。]]}
