,["80011"]={["key"]="80011",["language1"]=[[<color=#ffc146>【简介】</color>
「天灯映月」活动期间，完成猜谜即可获得奖励！

<color=#ffc146>【活动详情】</color>
1.活动开启后，每天解锁一个猜谜。选择正确的答案，即可获得奖励。
2.已开启但未完成的猜谜可以在活动的时间内继续进行。]],["id"]="80011",["language2"]=[[<color=#ffc146>【簡介】</color>
「天燈映月」活動期間，完成猜謎即可獲得獎勵！

<color=#ffc146>【活動詳情】</color>
1.活動開啟後，每天解鎖一個猜謎。選擇正確的答案，即可獲得獎勵。
2.已開啟但未完成的猜謎可以在活動的時間內繼續進行。]]}
