,["76225"]={["key"]="76225",["language1"]=[[<color=#ffc146>【简介】</color>
阈限禁区为周期轮换BOSS挑战玩法，玩家需要针对BOSS和增益效果进行配队与挑战，并按照伤害排名发放奖励。

<color=#ffc146>【玩法规则】</color>
1.BOSS每3天会进行轮换，在第4天0点结束挑战，并在第4天10点开启下一BOSS的挑战。
2.每次轮换仅有3次挑战机会，消耗完毕后可进行购买，排行榜将按照玩家本次挑战中的最高分进行记录和排名，模拟挑战不限次数且不会计入排名。
3.玩家不足80级的角色，在玩法中会自动将角色等级补强到80级，芯片，武装技能，跃升天赋，光环养成不受影响。当角色超过80级时，将按照原等级进行挑战。
4.挑战不同BOSS时，获得的增益不同，增益会很大程度上影响最终伤害，请合理根据BOSS特点及增益组建队伍。

<color=#ffc146>【奖励规则】</color>
1.奖励包括伤害奖励、排名奖励，奖励都会随周期轮换重置
2.伤害奖励分为多个伤害档位，只要在单次挑战中达到该伤害即可在结算时自动获得该奖励。
3.排名奖励将根据结束挑战时玩家在排行榜的排名进行结算，奖励将通过邮件进行发放。
4.奖励中获得的<color=#ffc146>残损精华</color>可在禁区商店中兑换各种奖励，禁区商店内奖励每月重置。]],["id"]="76225",["language4"]="none",["language3"]="None",["language2"]=[[<color=#ffc146>【簡介】</color>
閾限禁區為週期輪換BOSS挑戰玩法，玩家需要針對BOSS和增益效果進行配隊與挑戰，並按照傷害排名發放獎勵。

<color=#ffc146>【玩法規則】</color>
1.BOSS每3天會進行輪換，在第4天0點結束挑戰，並在第4天10點開啟下一BOSS的挑戰。
2.每次輪換僅有3次挑戰機會，消耗完畢後可進行購買，排行榜將按照玩家本次挑戰中的最高分進行記錄和排名，模擬挑戰不限次數且不會計入排名。
3.玩家不足80級的角色，在玩法中會自動將角色等級補強到80級，晶片，武裝技能，躍升天賦，光環養成不受影響。當角色超過80級時，將按照原等級進行挑戰。
4.挑戰不同BOSS時，獲得的增益不同，增益會很大程度上影響最終傷害，請合理根據BOSS特點及增益組建隊伍。

<color=#ffc146>【獎勵規則】</color>
1.獎勵包括傷害獎勵、排名獎勵，獎勵都會隨週期輪換重置
2.傷害獎勵分為多個傷害檔位，只要在單次挑戰中達到該傷害即可在結算時自動獲得該獎勵。
3.排名獎勵將根據結束挑戰時玩家在排行榜的排名進行結算，獎勵將通過郵件進行發放。
4.獎勵中獲得的<color=#ffc146>殘損精華</color>可在禁區商店中兌換各種獎勵，禁區商店內獎勵每月重置。]]}
