,["17101"]={["key"]="17101",["language1"]="本构建需要<color=#ffae00>通关0-2</color>后才会开启，总队长可以进行<color=#ffae00>最大30次</color>的10连构建，可<color=#ffae00>从30次的10连构建</color>中<color=#ffae00>选择1次作为最终结果</color>；每次构建后，可暂时保存当前构建结果；结果仅保留一次，若选择不同的构建结果，则会使用当前选择的结果覆盖此前的记录。",["id"]="17101",["language3"]="<color=#ffae00>0-2をクリア</color>すると開放されます。本構築は<color=#ffae00>最大30回</color>10連構築を行うことができます。<color=#ffae00>30回の10連構築</color>の結果から<color=#ffae00>1つだけ選べます</color>。毎回の構築結果は1つだけ一時的に保存できます。新しい結果を保存する場合、現在保存されている結果が上書きされます。",["language2"]="本構建需要<color=#ffae00>通關0-2</color>後才會開啟，總隊長可以進行<color=#ffae00>最大30次</color>的10連構建，可<color=#ffae00>從30次的10連構建</color>中<color=#ffae00>選擇1次作為最終結果</color>；每次構建後，可暫時保存當前構建結果；結果僅保留一次，若選擇不同的構建結果，則會使用當前選擇的結果覆蓋此前的記錄。"}
