,["91051"]={["key"]="91051",["language1"]=[[<color=#ffc146>限时竞技玩法：</color>
1.在指定时间内，限时竞技玩法入口开启，在对应时间内，可参与玩家与玩家之间的实时竞技。
2.不同的玩家之间，会根据基础积分进行匹配，会尽可能匹配到当前实力较为接近的玩家进行实时竞技。
3.必须配备三支队伍才可参加限时竞技，要想获得竞技胜利，最好以三支满编队伍进行竞技匹配！
4.在限时竞技中，双方所有角色都会获得额外增强BUFF，且随着操作数增加，双方也会逐渐获得增强。
5.限时竞技结束后，会根据胜负发放竞技积分，竞技积分用于评判指挥官的竞技段位；在较低段位下，限时竞技的失败不会扣除积分，指挥官们可以放心进行限时竞技；仅有段位达到“上尉”及以上的指挥官，在失败中会扣除少量积分。
6.在每一期限时竞技中，玩家每一次达到新的段位，都能获得对应段位设定的奖励，还会根据参与次数以及累计胜利场次发放目标奖励！
7.在每次赛季更新时，总部会根据版本以及队员强度等作为判断进行队员禁用，以考验指挥官们更灵活的编队配置；每期禁用角色不重复，因此不必担心队员无上场机会。
8.在战斗中若选择放弃，则视为认输；若在战斗中离线，则在回合倒计时结束后，玩家会进入自动操作模式。
9.限时竞技中，操作数为双方同时计算，且操作数上限为999，若操作数达到上限，则战斗结束，并且双方判负。

<color=#ffc146>好友竞技玩法：</color>
1.在活动开放期间，玩家可以邀请好友列表内在线的玩家进行好友竞技。
2.好友竞技玩法如限时竞技相同，但不受禁用角色限制，玩家可以使用所有队员进行好友竞技。
3.好友竞技胜负均不会获得或丢失竞技积分，因此也不会获得目标奖励。总队长可以大胆与好友进行好友竞技以尝试更多阵容哦！]],["id"]="91051",["language3"]="NONE",["language2"]=[[<color=#ffc146>限時競技玩法：</color>
1.在指定時間內，限時競技玩法入口開啟，在對應時間內，可參與玩家與玩家之間的即時競技。
2.不同的玩家之間，會根據基礎積分進行匹配，會盡可能匹配到當前實力較為接近的玩家進行即時競技。
3.必須配備三支隊伍才可參加限時競技，要想獲得競技勝利，最好以三支滿編隊伍進行競技匹配！
4.在限時競技中，雙方所有角色都會獲得額外增強BUFF，且隨著運算元增加，雙方也會逐漸獲得增強。
5.限時競技結束後，會根據勝負發放競技積分，競技積分用於評判指揮官的競技段位；在較低段位下，限時競技的失敗不會扣除積分，指揮官們可以放心進行限時競技；僅有段位達到“上尉”及以上的指揮官，在失敗中會扣除少量積分。
6.在每一期限時競技中，玩家每一次達到新的段位，都能獲得對應段位設定的獎勵，還會根據參與次數以及累計勝利場次發放目標獎勵！
7.在每次賽季更新時，總部會根據版本以及隊員強度等作為判斷進行隊員禁用，以考驗指揮官們更靈活的編隊配置；每期禁用角色不重複，因此不必擔心隊員無上場機會。
8.在戰鬥中若選擇放棄，則視為認輸；若在戰鬥中離線，則在回合倒計時結束後，玩家會進入自動操作模式。
9.限時競技中，運算元為雙方同時計算，且運算元上限為999，若運算元達到上限，則戰鬥結束，並且雙方判負。

<color=#ffc146>好友競技玩法：</color>
1.在活動開放期間，玩家可以邀請好友列表內在線的玩家進行好友競技。
2.好友競技玩法如限時競技相同，但不受禁用角色限制，玩家可以使用所有隊員進行好友競技。
3.好友競技勝負均不會獲得或丟失競技積分，因此也不會獲得目標獎勵。總隊長可以大膽與好友進行好友競技以嘗試更多陣容哦！]]}
