,["76088"]={["key"]="76088",["language1"]=[[<color=#ffc146>【简介】</color>
玩家将在一个迷雾地图内通过投掷骰子进行探索，每个地块格子上都有不同事件，玩家探索并击败地图内的BOSS即可通关

<color=#ffc146>【玩法规则】</color>
1.玩家每天会自动获得<color=#ffc146>20点</color>行动点数，消耗行动点数可以投掷骰子，根据骰子点数可以自由选择在地图内行走的目的地与行动路线。
2.踩到对应的格子上会触发不同的事件，直到击败地图内的任意3个BOSS即可解锁下一关卡。
3.玩法一共有3个关卡，每个关卡共有10个危险等级，不同关卡和危险等级会影响怪物难度与奖励。
4.玩家遇到BOSS时，如果战斗失败可以选择发出求援，其他玩家可在【支援协定】界面进行援助，援助和求援方均可获得奖励。
5.收集<color=#ffc146>秘境图志</color>可在【补给商店】中兑换奖励。

<color=#ffc146>【关卡说明】</color>
1.玩法一共有3个关卡，每个关卡中隐藏着4只BOSS，击败本关的任意3个BOSS通关即可解锁下一关卡。
2.玩家在进入关卡前，可以选择关卡的危险等级，通关任意关卡的危险等级后，其他关卡的危险等级也会解锁。
3.危险等级会在行动中自动提升，消耗行动点数、进行行走、触发事件都会获得危险等级经验值，累计一定经验后危险等级将会自动提升。
4.当危险等级过高时，可以选择<color=#ffc146>锁定危险等级或手动降低危险等级</color>，但降低危险等级后，不能再直接手动升回原等级。
5.在关卡中，BOSS血量和玩家队伍状态将会在战斗结束后继承，同一BOSS可以进行多次挑战。
6.探索过程中可能会遇到特殊BOSS，击败后可以获得额外奖励，特殊BOSS限制挑战时间，超出时限后将会消失。

<color=#ffc146>【求援规则】</color>
1.求援分为好友求援、全体求援，好友求援只对好友可见，全体求援则允许所有玩家进行援助。
2.进行援助可以获得奖励，每次活动可以获得的奖励内容存在上限，超出上限后不再能获得援助奖励，但依然可以进行援助。
3.每日可以进行3次求援，进行援助的次数不限。
4.援助奖励与怪物难度、对怪物造成的伤害有关，怪物难度越高，造成的伤害越高，获得的奖励越高；若击杀了BOSS，则可获得全额奖励。
5.发起求援后，即使退出关卡，该求援会保留，其他玩家击败后依然可以获得奖励。
6.只有通关过对应危险等级后，才能收到该危险等级的援助信息。]],["id"]="76088",["language3"]="None",["language2"]=[[<color=#ffc146>【簡介】</color>
玩家將在一個迷霧地圖內通過投擲骰子進行探索，每個地塊格子上都有不同事件，玩家探索並擊敗地圖內的BOSS即可通關

<color=#ffc146>【玩法規則】</color>
1.玩家每天會自動獲得<color=#ffc146>20點</color>行動點數，消耗行動點數可以投擲骰子，根據骰子點數可以自由選擇在地圖內行走的目的地與行動路線。
2.踩到對應的格子上會觸發不同的事件，直到擊敗地圖內的任意3個BOSS即可解鎖下一關卡。
3.玩法一共有3個關卡，每個關卡共有10個危險等級，不同關卡和危險等級會影響怪物難度與獎勵。
4.玩家遇到BOSS時，如果戰鬥失敗可以選擇發出求援，其他玩家可在【支援協定】介面進行援助，援助和求援方均可獲得獎勵。
5.收集<color=#ffc146>秘境圖志</color>可在【補給商店】中兌換獎勵。

<color=#ffc146>【關卡說明】</color>
1.玩法一共有3個關卡，每個關卡中隱藏著4只BOSS，擊敗本關的任意3個BOSS通關即可解鎖下一關卡。
2.玩家在進入關卡前，可以選擇關卡的危險等級，通關任意關卡的危險等級後，其他關卡的危險等級也會解鎖。
3.危險等級會在行動中自動提升，消耗行動點數、進行行走、觸發事件都會獲得危險等級經驗值，累計一定經驗後危險等級將會自動提升。
4.當危險等級過高時，可以選擇<color=#ffc146>鎖定危險等級或手動降低危險等級</color>，但降低危險等級後，不能再直接手動升回原等級。
5.在關卡中，BOSS血量和玩家隊伍狀態將會在戰鬥結束後繼承，同一BOSS可以進行多次挑戰。
6.探索過程中可能會遇到特殊BOSS，擊敗後可以獲得額外獎勵，特殊BOSS限制挑戰時間，超出時限後將會消失。

<color=#ffc146>【求援規則】</color>
1.求援分為好友求援、全體求援，好友求援只對好友可見，全體求援則允許所有玩家進行援助。
2.進行援助可以獲得獎勵，每次活動可以獲得的獎勵內容存在上限，超出上限後不再能獲得援助獎勵，但依然可以進行援助。
3.每日可以進行3次求援，進行援助的次數不限。
4.援助獎勵與怪物難度、對怪物造成的傷害有關，怪物難度越高，造成的傷害越高，獲得的獎勵越高；若擊殺了BOSS，則可獲得全額獎勵。
5.發起求援後，即使退出關卡，該求援會保留，其他玩家擊敗後依然可以獲得獎勵。
6.只有通關過對應危險等級後，才能收到該危險等級的援助資訊。]]}
