,["37029"]={["key"]="37029",["language1"]=[[<color=#ffc146>【简介】</color>
击败敌方，完成对应任务领取奖励。

<color=#ffc146>【规则】</color>
1.拟真演训的挑战不消耗燃料与限制次数。
2.除普通难度外，其他的难度都需要成功通过上一难度才能解锁]],["id"]="37029",["language3"]=[[<color=#ffc146>【説明】</color>
敵を撃破し、任務を達成して報酬を受け取る。

<color=#ffc146>【規則】</color>
1.シミュレーションバトルの挑戦は燃料の消耗や挑戦回数の制限がない。
2.普通以外の難易度はひとつ下の難易度をクリアすることで開放される。]],["language2"]=[[<color=#ffc146>【簡介】</color>
擊敗敵方，完成對應任務領取獎勵。

<color=#ffc146>【規則】</color>
1.擬真演訓的挑戰不消耗燃料與限制次數。
2.除普通難度外，其他的難度都需要成功通過上一難度才能解鎖]]}
