,["73015"]={["key"]="73015",["language1"]=[[<color=#ffc146>【简介】</color>
时光恋曲是特定角色的限时剧情活动。

<color=#ffc146>【活动详情】</color>
1.活动开启后，可与对应角色进行专属剧情交互等体验。根据不同选择，剧情可能含有多种分支与结局。
2.时光恋曲中出售的皮肤与插画仅在本活动中出售，不会在商城复刻。]],["id"]="73015",["language2"]=[[<color=#ffc146>【簡介】</color>
時光戀曲是特定角色的限時劇情活動。

<color=#ffc146>【活動詳情】</color>
1.活動開啟後，可與對應角色進行專屬劇情交互等體驗。根據不同選擇，劇情可能含有多種分支與結局。
2.時光戀曲中出售的皮膚與插畫僅在本活動中出售，不會在商城複刻。]]}
