,["17051"]={["key"]="17051",["language1"]=[[※在该构建中，若连续获得2次获得6星角色时，均没有出现选中角色，则在第3次获得6星角色时，必定为所选角色。
※无论是否达到累计次数，当构建获得该角色后，则次数会进行重置]],["id"]="17051",["language3"]=[[※構築する際に、出現した★6キャラは2回連続で選択したキャラが出なかった場合、3回目に出現した★6キャラは必ず選択したキャラになる
※構築で選択したキャラを獲得した時点で、確定までのカウントがリセットされます]],["language2"]=[[※在該構建中，若連續獲得2次獲得6星角色時，均沒有出現選中角色，則在第3次獲得6星角色時，必定為所選角色。
※無論是否達到累計次數，當構建獲得該角色後，則次數會進行重置]]}
