,["10444"]={["key"]="10444",["language1"]=[[<color=#ffc146>【简介】</color>
 在改造中心中，可消耗破碎程式对芯片进行改造提升。

<color=#ffc146>【规则】</color>
1.改造能够使芯片变为更高等级的芯片，但部位是<color=#ffc146>随机</color>的。
2.改造芯片需要消耗破碎程序与时间，需要改造的芯片品质越高，消耗的破碎程式越多，改造的时间越久。
3.破碎程式可通过分解一定品质以上的芯片获得，分解芯片的品质越高，获得的破碎程序越多。]],["id"]="10444",["language3"]=[[<color=#ffc146>【説明】</color>
開発局では、破損データを消費してチップを改造することができる。

<color=#ffc146>【規則】</color>
1.改造することで、より高品質なチップを作ることができる。しかし部位は<color=#ffc146>ランダム</color>で決定される。
2.チップを改造するには破損データや時間が必要となる。改造するチップの品質が高いほど、破損データの消費量が多くなり、必要時間が長くなる。
3.破損データは一定品質以上のチップを分解することで獲得できる。分解されたチップの品質が高いほど、破損データの獲得量が多くなる。]],["language2"]=[[<color=#ffc146>【簡介】</color>
 在改造中心中，可消耗破碎程式對晶片進行改造提升。

<color=#ffc146>【規則】</color>
1.
2.
3.]]}
