,["17141"]={["key"]="17141",["language1"]="<color=#FF7781>【注意】</color>本构建属于【轮换构建】，其构建次数保底会一直累计于【轮换构建】中，与其他类型的构建次数保底相互独立计算，互不影响。",["id"]="17141",["language3"]="【<color=#ffae00>注意</color>】本構築は【定期構築】に属します。確定までのカウントは別種類の構築とは互いに独立しており、共通しません。",["language2"]="<color=#FF7781>【注意】</color>本構建屬於【輪換構建】，其構建次數保底會一直累計於【輪換構建】中，與其他類型的構建次數保底相互獨立計算，互不影響。"}
