,["330010"]={["key"]="330010",["language1"]=[[<color=#ffc146>【简介】</color>
「予金回赠」 是通过消费获得奖励的活动。

<color=#ffc146>【活动说明】</color>
1.活动期间，通过完成任务即可领取奖励。
2.仅在活动期间内的消费才会累计任务进度，游戏内所有的直接充值或消费均可计算入任务进度。
3.「予金回赠」内的任务可多个同时完成，例：当天充值30元，则可同时完成6元、18元以及30元的“消费共1天”任务。
4.每日凌晨3点刷新当天累计消费金额。]],["id"]="330010",["language3"]="None",["language2"]=[[<color=#ffc146>【簡介】</color>
「予金回贈」 是通過累計充值獲得獎勵的活動。

<color=#ffc146>【活動說明】</color>
1.活動期間，通過完成充值任務即可領取獎勵。
2.僅在活動期間內的充值才會累計任務進度。
3.「予金回贈」內的充值任務均為累計充值，多個任務可同時完成，例：當天充值170元，則可同時完成33元、100元以及170元的“充值共1天”任務。
4.每日淩晨3點刷新當天累計充值金額。]]}
,["17109"]={["key"]="17109",["language1"]=[[在所有<color=#ffae00>【核心构建】</color>中构建获取<color=#FF3300>6星</color>角色的基础概率为<color=#ffae00>2%</color>，综合概率为<color=#ffae00>3%（含保底)</color>，<color=#FFCC00>5星</color>队员的基础概率为<color=#ffae00>8%</color>，<color=#6666FF>4星</color>队员的基础概率为<color=#ffae00>40%</color>，<color=#33CCFF>3星</color>队员的基础概率为<color=#ffae00>50%</color>。10连构建必得<color=#FFCC00>5星</color>或以上的队员。
<color=#ffae00>最多50次</color>构建<color=#ffae00>必定</color>能获得保底获取<color=#FF3300>6星</color>角色。]],["id"]="17109",["language3"]=[[<color=#ffae00>【スタンダード構築】</color>の中で<color=#FF3300>★6</color>キャラの基本出現率は<color=#ffae00>2%</color>、総合確率は<color=#ffae00>3%（確定を含む)</color>。<color=#FFCC00>★5</color>キャラの基本確率は<color=#ffae00>8%</color>。<color=#6666FF>★4</color>キャラの基本出現率は<color=#ffae00>40%</color>。<color=#33CCFF>★3</color>キャラの基本出現率は<color=#ffae00>50%</color>。10連構築は<color=#FFCC00>★5</color>キャラが1体確定します。
<color=#ffae00>最大50回</color>構築で<color=#FF3300>★6</color>キャラが確定します。]],["language2"]=[[在所有<color=#ffae00>【核心構建】</color>中構建獲取<color=#FF3300>6星</color>角色的基礎機率為<color=#ffae00>2%</color>，綜合機率為<color=#ffae00>3%（含保底)</color>，<color=#FFCC00>5星</color>隊員的基礎機率為<color=#ffae00>8%</color>，<color=#6666FF>4星</color>隊員的基礎機率為<color=#ffae00>40%</color>，<color=#33CCFF>3星</color>隊員的基礎機率為<color=#ffae00>50%</color>。10連構建必得<color=#FFCC00>5星</color>或以上的隊員。
<color=#ffae00>最多50次</color>構建<color=#ffae00>必定</color>能獲得保底獲取<color=#FF3300>6星</color>角色。]]}
