,["17191"]={["key"]="17191",["language1"]=[[第2次至第9次：获取相同<color=#FF3300>6星</color>角色时，每次将转化为对应角色的<color=#ffae00>「星源」*1</color>和<color=#9a80b7>「自选星尘券」*100</color>。
第10次及之后获取相同角色：将会获得<color=#9a80b7>「自选星尘券」*300</color>。]],["id"]="17191",["language3"]=[[2回目から9回目まで：重複した<color=#FF3300>★6</color>キャラを1体獲得するにつき、そのキャラ専用の<color=#ffae00>「星源」x1</color>と<color=#ffae00>「レジェンド星塵券」x10</color>を獲得する。
10回目以降：そのキャラ専用の<color=#ffae00>「星源」x1</color>と<color=#ffae00>「レジェンド星塵券」x15</color>を獲得する。]],["language2"]=[[第2次至第9次：獲取相同<color=#FF3300>6星</color>角色時，每次將轉化為對應角色的<color=#ffae00>「星源」*1</color>和<color=#9a80b7>「自選星塵券」*100</color>。
第10次及之後獲取相同角色：將會獲得<color=#9a80b7>「自選星塵券」*300</color>。]]}
