,["45041"]={["key"]="45041",["language1"]=[[<color=#ffc146>【简介】</color>
「星辉回溯」 是推出的限时福利活动，专为热爱收藏外观的玩家打造。
在活动期间，激活「星辉回溯」资格后，每当你成功购买一款当前版本复刻时装，即可获得一份专属返利奖励！

<color=#ffc146>【活动参与方式】</color>
1.活动开启后，前往【星辉回溯】界面购买激活。
2.购买成功后，返利资格激活，仅对“本版本周期内的复刻时装”有效。（当前版本时装商店内，除上新时装外的复刻时装）
3.每当成功购买一款符合条件的新时装，返利奖励将立即激活。
4.前往【星辉回溯】界面即可逐个领取对应奖励。

<color=#ffc146>【活动限制说明】</color>
1.本活动仅对版本活动期间复刻时装有效，不适用于上新时装。
2.资格激活与时装购买的顺序不做限制。只要在活动期间内完成激活资格与购买指定范围的时装，即可获得对应返利奖励。
3.玩家仅通过粲晶、直购的方式在时装商店内购买指定范围内时装可以获得返利，通过礼包、扭蛋、兑换码等其他途径获得时装无法获得返利。
4.每款时装绑定一份返利奖励，仅限领取一次。
5.星辉回溯活动中，购买指定范围内的时装数量存在上限，超出购买上限将无法获取更多奖励。
6.所有皮肤返利奖励可在活动期间内通过【星辉回溯】界面手动领取。活动结束后，未及时领取的奖励将统一通过游戏内邮件自动发放。
请注意：邮件发放可能存在延迟，建议在活动期内及时领取以避免等待时间。]],["id"]="45041",["language3"]="none",["language2"]=[[<color=#ffc146>【簡介】</color>
「星輝回溯」 是推出的限時福利活動，專為熱愛收藏外觀的玩家打造。
在活動期間，啟動「星輝回溯」資格後，每當你成功購買一款當前版本複刻時裝，即可獲得一份專屬返利獎勵！

<color=#ffc146>【活動參與方式】</color>
1.活動開啟後，前往【星輝回溯】介面購買啟動。
2.購買成功後，返利資格啟動，僅對“本版本週期內的複刻時裝”有效。（當前版本時裝商店內，除上新時裝外的複刻時裝）
3.每當成功購買一款符合條件的新時裝，返利獎勵將立即啟動。
4.前往【星輝回溯】介面即可逐個領取對應獎勵。

<color=#ffc146>【活動限制說明】</color>
1.本活動僅對版本活動期間複刻時裝有效，不適用於上新時裝。
2.資格啟動與時裝購買的順序不做限制。只要在活動期間內完成啟動資格與購買指定範圍的時裝，即可獲得對應返利獎勵。
3.玩家僅通過粲晶、直購的方式在時裝商店內購買指定範圍內時裝可以獲得返利，通過禮包、扭蛋、兌換碼等其他途徑獲得時裝無法獲得返利。
4.每款時裝綁定一份返利獎勵，僅限領取一次。
5.星輝回溯活動中，購買指定範圍內的時裝數量存在上限，超出購買上限將無法獲取更多獎勵。
6.所有皮膚返利獎勵可在活動期間內通過【星輝回溯】介面手動領取。活動結束後，未及時領取的獎勵將統一通過遊戲內郵件自動發放。
請注意：郵件發放可能存在延遲，建議在活動期內及時領取以避免等待時間。]]}
