,["45036"]={["key"]="45036",["language1"]=[[<color=#ffc146>【简介】</color>
「悦购优惠」 是推出的限时福利活动，专为热爱收藏外观的玩家打造。
在活动期间，购买图册交易所内<color=#ffc146>复刻</color>插画可完成活动任务，获得对应任务奖励

<color=#ffc146>【活动参与方式】</color>
1.活动开启后，前往商店购买对应的插画即可完成任务。
2.购买插画后将会发放对应的优惠券。
3.每个任务均可完成指定次数，每完成一次可以获得1张对应的优惠券。

<color=#ffc146>【活动适用范围说明】</color>
1.本活动仅在活动持续期间，在图册交易所内购买对应插画可完成任务。
2.活动中复刻插画为除常驻插画<color=#ffc146>曦光盛宴、导购进修课</color>，与上新插画外的其他插画。
4.<color=#ffc146>追忆优惠券</color>可用于在粲晶方式购买复刻插画时抵扣一定数量的粲晶。
5.<color=#ffc146>追忆优惠券</color>将在活动结束时失效，请在有效期内使用。]],["id"]="45036",["language4"]="none",["language3"]="none",["language2"]=[[<color=#ffc146>【簡介】</color>
「悅購優惠」 是推出的限時福利活動，專為熱愛收藏外觀的玩家打造。
在活動期間，購買圖冊交易所內<color=#ffc146>複刻</color>插畫可完成活動任務，獲得對應任務獎勵

<color=#ffc146>【活動參與方式】</color>
1.活動開啟後，前往商店購買對應的插畫即可完成任務。
2.購買插畫後將會發放對應的優惠券。
3.每個任務均可完成指定次數，每完成一次可以獲得1張對應的優惠券。

<color=#ffc146>【活動適用範圍說明】</color>
1.本活動僅在活動持續期間，在圖冊交易所內購買對應插畫可完成任務。
2.活動中複刻插畫為除常駐插畫<color=#ffc146>曦光盛宴、導購進修課</color>，與上新插畫外的其他插畫。
4.<color=#ffc146>追憶優惠券</color>可用於在粲晶方式購買複刻插畫時抵扣一定數量的粲晶。
5.<color=#ffc146>追憶優惠券</color>將在活動結束時失效，請在有效期內使用。]]}
