,["17119"]={["key"]="17119",["language1"]="在所有<color=#ffae00>【特装构建】</color>中构建获取<color=#FF3300>6星</color>角色的基础概率为<color=#ffae00>2%</color>，综合概率为<color=#ffae00>3%（含保底)</color>，<color=#FFCC00>5星</color>队员的基础概率为<color=#ffae00>8%</color>，<color=#6666FF>4星</color>队员的基础概率为<color=#ffae00>40%</color>，<color=#33CCFF>3星</color>队员的基础概率为<color=#ffae00>50%</color>。10连构建必得<color=#FFCC00>6星</color>队员。",["id"]="17119",["language3"]="<color=#ffae00>【スタートダッシュ構築】</color>の中で<color=#FF3300>★6</color>キャラの基本出現率は<color=#ffae00>2%</color>、総合確率は<color=#ffae00>3%（確定を含む)</color>。<color=#FFCC00>★5</color>キャラの基本確率は<color=#ffae00>8%</color>。<color=#6666FF>★4</color>キャラの基本出現率は<color=#ffae00>40%</color>。<color=#33CCFF>★3</color>キャラの基本出現率は<color=#ffae00>50%</color>。10連構築は<color=#FFCC00>★6</color>キャラが1体確定します。",["language2"]="在所有<color=#ffae00>【特裝構建】</color>中構建獲取<color=#FF3300>6星</color>角色的基礎機率為<color=#ffae00>2%</color>，綜合機率為<color=#ffae00>3%（含保底)</color>，<color=#FFCC00>5星</color>隊員的基礎機率為<color=#ffae00>8%</color>，<color=#6666FF>4星</color>隊員的基礎機率為<color=#ffae00>40%</color>，<color=#33CCFF>3星</color>隊員的基礎機率為<color=#ffae00>50%</color>。10連構建必得<color=#FFCC00>6星</color>隊員。"}
