,["37080"]={["key"]="37080",["language1"]=[[<color=#ffc146>【简介】</color>
连锁阵线活动会随着版本定期开放，活动期间内挑战boss可以获得积分奖励。

<color=#ffc146>【规则】</color>
1.连锁阵线中的得分奖励会周期性开放与关闭，活动开放时需要挑战当期的挑战目标获得积分。
2.连锁阵线每期会有固定的挑战目标，总队长可以根据自己的能力挑战不同难度的boss，挑战成功即可获得积分。
3.在连锁阵线中，对应的挑战目标会有着独特的强化buff，并且每一期都会有一个boss有得分加成。
4.总队长在编队时，每只队伍需要使用不同的队员（包含助战），并且可以选择支援技能来强化队伍，每个队伍可以选择相同的支援技能。
5.连锁阵线的挑战难度等级与特遣挑战（原历战试炼）中的挑战难度等级相同，总队长可以在特遣挑战中单独挑战目标boss。
6.在连锁阵线挑战中，若是总队长消耗回合数较多且对boss造成的伤害较低时，获得分数将会减少（最低为0）。
7.连锁阵线中的挑战不消耗燃料。
8.连锁战线活动结束后，总队长仍然可以挑战目标boss，但无法获得积分奖励，积分奖励会在下次活动开放时刷新。
9.排行榜内会显示总队长的挑战最高积分（不限难度），根据最高积分来进行排名展示。]],["id"]="37080",["language3"]="none",["language2"]=[[<color=#ffc146>【簡介】</color>
連鎖陣線活動會隨著版本定期開放，活動期間內挑戰boss可以獲得積分獎勵。

<color=#ffc146>【規則】</color>
1.連鎖陣線中的得分獎勵會週期性開放與關閉，活動開放時需要挑戰當期的挑戰目標獲得積分。
2.連鎖陣線每期會有固定的挑戰目標，總隊長可以根據自己的能力挑戰不同難度的boss，挑戰成功即可獲得積分。
3.在連鎖陣線中，對應的挑戰目標會有著獨特的強化buff，並且每一期都會有一個boss有得分加成。
4.總隊長在編隊時，每只隊伍需要使用不同的隊員（包含助戰），並且可以選擇支援技能來強化隊伍，每個隊伍可以選擇相同的支援技能。
5.連鎖陣線的挑戰難度等級與特遣挑戰（原曆戰試煉）中的挑戰難度等級相同，總隊長可以在特遣挑戰中單獨挑戰目標boss。
6.在連鎖陣線挑戰中，若是總隊長消耗回合數較多且對boss造成的傷害較低時，獲得分數將會減少（最低為0）。
7.連鎖陣線中的挑戰不消耗燃料。
8.連鎖戰線活動結束後，總隊長仍然可以挑戰目標boss，但無法獲得積分獎勵，積分獎勵會在下次活動開放時刷新。
9.排行榜內會顯示總隊長的挑戰最高積分（不限難度），根據最高積分來進行排名展示。]]}
