,["17209"]={["key"]="17209",["language1"]="在所有<color=#ffae00>【定制构建】</color>中构建获取<color=#FF3300>6星</color>角色的基础概率为<color=#ffae00>2%</color>，综合概率为<color=#ffae00>3%（含保底)</color>，<color=#FFCC00>5星</color>队员的基础概率为<color=#ffae00>8%</color>，<color=#6666FF>4星</color>队员的基础概率为<color=#ffae00>40%</color>，<color=#33CCFF>3星</color>队员的基础概率为<color=#ffae00>50%</color>。10连构建必得<color=#FFCC00>5星</color>或以上队员。最多50次构建必定能获得保底获取<color=#FF3300>6星</color>角色。",["id"]="17209",["language3"]=[[<color=#ffae00>【指名召集】</color>の中で<color=#FF3300>☆6</color>キャラの基本出現率は<color=#ffae00>2%</color>。<color=#FFCC00>☆5</color>キャラの基本確率は<color=#ffae00>8%</color>。<color=#6666FF>☆4</color>キャラの基本出現率は<color=#ffae00>40%</color>。<color=#33CCFF>☆3</color>キャラの基本出現率は<color=#ffae00>50%</color>。10連召集は<color=#FFCC00>☆5</color>キャラが1体確定します。
<color=#ffae00>最大50回</color>召集で<color=#FF3300>☆6</color>キャラが確定します。]],["language2"]="在所有<color=#ffae00>【定制構建】</color>中構建獲取<color=#FF3300>6星</color>角色的基礎概率為<color=#ffae00>2%</color>，綜合概率為<color=#ffae00>3%（含保底)</color>，<color=#FFCC00>5星</color>隊員的基礎概率為<color=#ffae00>8%</color>，<color=#6666FF>4星</color>隊員的基礎概率為<color=#ffae00>40%</color>，<color=#33CCFF>3星</color>隊員的基礎概率為<color=#ffae00>50%</color>。10連構建必得<color=#FFCC00>5星</color>或以上隊員。最多50次構建必定能獲得保底獲取<color=#FF3300>6星</color>角色。"}
