,["10440"]={["key"]="10440",["language1"]=[[<color=#ffc146>【简介】</color>
玩家可自由布置宿舍，并与入驻队员进行互动或礼物赠送，宿舍内的队员会随时间恢复心情。

<color=#ffc146>【规则】</color>
1.宿舍中以房间作为独立单位存在。
2.每个房间都能布置独立的家具与入驻队员。
3.队员可以与部分家具产生特殊交互。
4.每个家具都有着自己的舒适度，将家具布置到对应房间中即可增加该房间的舒适度，舒适度越高，此房间内入驻的队员心情恢复越快。]],["id"]="10440",["language3"]=[[<color=#ffc146>【説明】</color>
プレイヤーは自由に寮舎の配置を変更したり、隊員と交流したりできる。寮舎内の隊員は時間の経過につれ、機嫌が回復する。

<color=#ffc146>【規則】</color>
1.寮舎内のルームはそれぞれ独立した存在。
2.ルームごとに独立した家具や人員を配置することができる。
3.一部の家具はキャラクターの特殊のモーションが鑑賞できる。
4.家具にはそれぞれ快適度が設定されている。快適度が高いほど、ルーム内に配置されたキャラクターの機嫌の回復速度が上がる]],["language2"]=[[<color=#ffc146>【簡介】</color>
玩家可自由佈置宿舍，並與入駐隊員進行互動或禮物贈送，宿舍內的隊員會隨時間恢復心情。

<color=#ffc146>【規則】</color>
1.宿舍中以房間作為獨立單位存在。
2.每個房間都能佈置獨立的傢俱與入駐隊員。
3.隊員可以與部分傢俱產生特殊互動。
4.每個傢俱都有著自己的舒適度，將傢俱佈置到對應房間中即可增加該房間的舒適度，舒適度越高，此房間內入駐的隊員心情恢復越快。]]}
,["33056"]={["key"]="33056",["language1"]=[[<color=#ffc146>限时军演玩法：</color>
1.在指定时间内，限时军演玩法入口开启，在对应时间内，可参与玩家与玩家之间的实时军演。
2.不同的玩家之间，会根据基础积分进行匹配，会尽可能匹配到当前实力较为接近的玩家进行实时军演。
3.必须配备三支队伍才可参加限时军演，要想获得军演胜利，最好以三支满编队伍进行军演匹配！
4.在限时军演中，双方所有角色都会获得额外增强BUFF，且随着操作数增加，双方也会逐渐获得增强。
5.限时军演结束后，会根据胜负发放军演积分，军演积分用于评判总队长的军演段位；在较低段位下，限时军演的失败不会扣除积分，总队长们可以放心进行限时军演；仅有段位达到“上尉”及以上的总队长，在失败中会扣除少量积分。
6.在每一期限时军演中，玩家每一次达到新的段位，都能获得对应段位设定的奖励，还会根据参与次数以及累计胜利场次发放目标奖励！
7.在每次赛季更新时，总部会根据版本以及队员强度等作为判断进行队员禁用，以考验总队长们更灵活的编队配置；每期禁用角色不重复，因此不必担心队员无上场机会。
8.在战斗中若选择放弃，则视为认输；若在战斗中离线，则在回合倒计时结束后，玩家会进入自动操作模式。
9.限时军演中，操作数为双方同时计算，且操作数上限为999，若操作数达到上限，则战斗结束，并且双方判负。

<color=#ffc146>好友军演玩法：</color>
1.在活动开放期间，玩家可以邀请好友列表内在线的玩家进行好友军演。
2.好友军演玩法如限时军演相同，但不受禁用角色限制，玩家可以使用所有队员进行好友军演。
3.好友军演胜负均不会获得或丢失军演积分，因此也不会获得目标奖励。总队长可以大胆与好友进行好友军演以尝试更多阵容哦！]],["id"]="33056",["language2"]=[[<color=#ffc146>限時軍演玩法：</color>
1.在指定時間內，限時軍演玩法入口開啟，在對應時間內，可參與玩家與玩家之間的即時軍演。
2.不同的玩家之間，會根據基礎積分進行匹配，會盡可能匹配到當前實力較為接近的玩家進行即時軍演。
3.必須配備三支隊伍才可參加限時軍演，要想獲得軍演勝利，最好以三支滿編隊伍進行軍演匹配！
4.在限時軍演中，雙方所有角色都會獲得額外增強BUFF，且隨著操作數增加，雙方也會逐漸獲得增強。
5.限時軍演結束後，會根據勝負發放軍演積分，軍演積分用於評判總隊長的軍演段位；在較低段位下，限時軍演的失敗不會扣除積分，總隊長們可以放心進行限時軍演；僅有段位達到“上尉”及以上的總隊長，在失敗中會扣除少量積分。
6.在每一期限時軍演中，玩家每一次達到新的段位，都能獲得對應段位設定的獎勵，還會根據參與次數以及累計勝利場次發放目標獎勵！
7.在每次賽季更新時，總部會根據版本以及隊員強度等作為判斷進行隊員禁用，以考驗總隊長們更靈活的編隊配置；每期禁用角色不重複，因此不必擔心隊員無上場機會。
8.在戰鬥中若選擇放棄，則視為認輸；若在戰鬥中離線，則在回合倒計時結束後，玩家會進入自動操作模式。
9.限時軍演中，操作數為雙方同時計算，且操作數上限為999，若操作數達到上限，則戰鬥結束，並且雙方判負。

<color=#ffc146>好友軍演玩法：</color>
1.在活動開放期間，玩家可以邀請好友列表內在線的玩家進行好友軍演。
2.好友軍演玩法如限時軍演相同，但不受禁用角色限制，玩家可以使用所有隊員進行好友軍演。
3.好友軍演勝負均不會獲得或丟失軍演積分，因此也不會獲得目標獎勵。總隊長可以大膽與好友進行好友軍演以嘗試更多陣容哦！]]}
,["76216"]={["key"]="76216",["language1"]="新记录！",["id"]="76216",["language4"]="none",["language3"]="新記録！",["language2"]="新記錄！"}
,["15102"]={["key"]="15102",["language1"]=[[<color=#ffc146>【简介】</color>
离开地球，基地的一切都得自给自足，寻找更多的物资，为了明天。

<color=#ffc146>【规则】</color>
1.每日副本分为资源采集、芯片嵌合、跃升行动三大类型。
2.在各类型副本中，资源采集可获得各类养成资源与通用货币；芯片嵌合可获得相同套装下的随机部件芯片；而跃升行动可获得不同阵营的特定养成材料。
3.通过每日探索副本的某一层副本时，需要玩家的<color=#ffc146>探索等级</color>满足要求才能解锁其下一层的挑战资格。
4.副本的层数越高，战斗消耗的燃料数越多，挑战难度越大，掉落的奖励越丰富。

<color=#ffc146>【类型掉落加成】</color>
1.玩家可通过主动开启类型掉落加成的方式，来增加该类型副本胜利后的奖励数量，每次挑战成功都会消耗加成次数。
2.同一类型的副本（如资源采集内的四个副本，限时类型的活动副本）会共享类型掉落加成的次数消耗，所有被消耗的次数都会在每日凌晨3点进行重置。

<color=#ffc146>【核心开发简介】
</color>汇集功能性副本入口，后续非日常循环类副本都会陆续加入此页签。

<color=#ffc146>【超维跃升】</color>规则说明：
1.每周一凌晨3:00，会自动发放3张挑战门票，用于进入超维跃升副本。
2.门票无法叠加，最多保留3张，请合理安排挑战时间。
3.副本不参与每日掉落加成次数的共享，不受日常次数限制。]],["id"]="15102",["language3"]=[[<color=#ffc146>【説明】</color>
地球から遠く離れた今、必要な資源は全部現地で調達しなければならない。明日のために、ガンガン集めよう。

<color=#ffc146>【規則】</color>
1.デイリー探索は資源採集、チップ嵌合、躍昇行動の3種類に分かれている。
2.資源採集は育成素材や共通貨幣、チップ嵌合はランダム部位のチップ、躍昇行動は各武装タイプの躍昇素材が入手できる。
3.ディリー探索の一部のクエストは<color=#ffc146>プレイヤーレベル</color>が条件を満たした後に開放される。
4.クエストの難易度が高いほど、消費する燃料が高くなり、ドロップ報酬がよくなる。

<color=#ffc146>【ドロップボーナス】</color>
1.ドロップボーナスを使用すると、クエストクリア時に使用回数が消費され、報酬が増加する。
2.同種類のクエストにおけるドロップボーナス回数が共通である。消費されたドロップボーナス回数は毎日4時に更新される。]],["language2"]=[[<color=#ffc146>【簡介】</color>
離開地球，基地的一切都得自給自足，尋找更多的物資，為了明天。

<color=#ffc146>【規則】</color>
1.每日副本分為資源採集、晶片嵌合、躍升行動三大類型。
2.在各類型副本中，資源採集可獲得各類養成資源與通用貨幣；晶片嵌合可獲得相同套裝下的隨機部件晶片；而躍升行動可獲得不同陣營的特定養成材料。
3.通過每日探索副本的某一層副本時，需要玩家的<color=#ffc146>探索等級</color>滿足要求才能解鎖其下一層的挑戰資格。
4.副本的層數越高，戰鬥消耗的燃料數越多，挑戰難度越大，掉落的獎勵越豐富。

<color=#ffc146>【類型掉落加成】</color>
1.玩家可通過主動開啟類型掉落加成的方式，來增加該類型副本勝利後的獎勵數量，每次挑戰成功都會消耗加成次數。
2.同一類型的副本（如資源採集內的四個副本，限時類型的活動副本）會共用類型掉落加成的次數消耗，所有被消耗的次數都會在每日淩晨3點進行重置。

<color=#ffc146>【核心開發簡介】
</color>匯集功能性副本入口，後續非日常循環類副本都會陸續加入此頁簽。

<color=#ffc146>【超維躍升】</color>規則說明：
1.每週一淩晨3:00，會自動發放3張挑戰門票，用於進入超維躍升副本。
2.門票無法疊加，最多保留3張，請合理安排挑戰時間。
3.副本不參與每日掉落加成次數的共用，不受日常次數限制。]]}
