,["22113"]={["key"]="22113",["language1"]=[[温暖时光，一路同行。
愿总队长们常怀喜悦，事事顺心~
相伴的每一天都值得纪念，在这特别的纪念日中，诚邀您携手共庆。

专属祝福将于 <color=#ffc146>6 月 24 日 </color> 通过邮件发送，请留意邮箱。]],["id"]="22113",["language3"]=[[温かな時間を、これからも共に。
総隊長の皆様に、喜びあふれる日々と、穏やかな幸せが訪れますように。
共に歩んできた一日一日は、どれもかけがえのない思い出です。この特別な記念日を、ぜひ一緒にお祝いしましょう。

特別な祝福は、<color=#ffc146>6月24日</color>にメールにてお届けいたします。ぜひご確認ください。]],["language2"]=[[溫暖時光，一路同行。
願總隊長們常懷喜悅，事事順心~
相伴的每一天都值得紀念，在這特別的紀念日中，誠邀您攜手共慶。

專屬祝福將於 <color=#ffc146>6 月 30 日 </color> 通過郵件發送，請留意郵箱。]]}
