,["37088"]={["key"]="37088",["language1"]=[[<color=#ffc146>【简介】</color>
历战试炼活动包含连锁阵线玩法与特遣挑战玩法，两者均为常驻玩法，活动奖励会随着版本开放，活动期间内挑战对应boss可以获得奖励。

<color=#ffc146>【规则】</color>
1.在历战试炼中，总队长可以自由选择不同模式进行挑战，。
2.连锁阵线每期会有固定的挑战目标，总队长可以根据自己的能力挑战不同难度的boss，挑战成功即可获得积分。
3.在连锁阵线中，对应的挑战目标会有着独特的强化buff，并且每一期都会有一个boss有得分加成。
4.总队长在编队时，每只队伍需要使用不同的队员（包含助战），并且可以选择支援技能来强化队伍，每个队伍可以选择相同的支援技能。
5.连锁阵线的挑战难度等级与特遣挑战（原历战试炼）中的挑战难度等级相同，总队长可以在特遣挑战中单独挑战目标boss。
6.在连锁阵线挑战中，若是总队长消耗回合数较多且对boss造成的伤害较低时，获得分数将会减少（最低为0）。
7.连锁阵线中的挑战不消耗燃料。
8.连锁战线活动结束后，总队长仍然可以挑战目标boss，但无法获得积分奖励，积分奖励会在下次活动开放时刷新。
9.排行榜内会显示总队长的挑战最高积分（不限难度），根据最高积分来进行排名展示。]],["id"]="37088",["language3"]=[[<color=#ffc146>【概要】</color>
歴戦試練では、「連鎖戦線」と「特遣挑戦」の2つの常設コンテンツがあります。イベント報酬はバージョンに応じて順次開放され、開催期間中に対象BOSSへ挑戦することで報酬を獲得できます。

<color=#ffc146>【ルール】</color>
1.歴戦試練では、総隊長は自由に挑戦するモードを選択できます。
2.連鎖戦線では、各開催期間ごとに固定の挑戦対象が設定されます。総隊長は自身の戦力に応じて異なる難易度のBOSSに挑戦でき、クリアするとスコアを獲得できます。
3.連鎖戦線では、対象BOSSごとに固有の強化バフが付与されます。また、各開催期間ごとに1体のBOSSがスコアボーナスの対象となります。
4.編成時、各部隊では異なる隊員を使用する必要があります（サポートを含む）。また、部隊を強化する支援スキルを選択でき、各部隊で同じ支援スキルを選択することも可能です。
5.連鎖戦線の挑戦難易度は、特遣挑戦（旧・歴戦試練）における挑戦難易度と同一です。総隊長は特遣挑戦で対象BOSSに個別挑戦することもできます。
6.連鎖戦線では、消費したターン数が多く、かつBOSSに与えたダメージが少ない場合、獲得スコアが減少します（最低0点）。
7.連鎖戦線での挑戦では、燃料を消費しません。
8.連鎖戦線の開催期間終了後も、総隊長は対象BOSSに挑戦できますが、スコア報酬は獲得できません。スコア報酬は次回開催時にリセットされます。
9.ランキングには、総隊長が獲得した最高スコアが表示されます（難易度不問）。順位は最高スコアに基づいて決定されます。]],["language2"]=[[ <color=#ffc146>【簡介】</color>
歷戰試煉活動包含連鎖陣線玩法與特遣挑戰玩法，兩者均為常駐玩法，活動獎勵會隨著版本開放，活動期間內挑戰對應boss可以獲得獎勵。

<color=#ffc146>【規則】</color>
1.在歷戰試煉中，總隊長可以自由選擇不同模式進行挑戰，。
2.連鎖陣線每期會有固定的挑戰目標，總隊長可以根據自己的能力挑戰不同難度的Boss，挑戰成功即可獲得積分。
3.在連鎖陣線中，對應的挑戰目標會有著獨特的強化Buff，並且每一期都會有一個Boss有得分加成。
4.總隊長在編隊時，每支隊伍需要使用不同的隊員（包含助戰），並且可以選擇支援技能來強化隊伍，每個隊伍可以選擇相同的支援技能。
5.連鎖陣線的挑戰難度等級與特遣挑戰（原歷戰試煉）中的挑戰難度等級相同，總隊長可以在特遣挑戰中單獨挑戰目標Boss。
6.在連鎖陣線挑戰中，若是總隊長消耗回合數較多且對Boss造成的傷害較低時，獲得分數將會減少（最低為0）。
7.連鎖陣線中的挑戰不消耗燃料。
8.連鎖戰線活動結束後，總隊長仍然可以挑戰目標Boss，但無法獲得積分獎勵，積分獎勵會在下次活動開放時刷新。
9.排行榜內會顯示總隊長的挑戰最高積分（不限難度），根據最高積分來進行排名展示。]]}
