,["17140"]={["key"]="17140",["language1"]="在所有<color=#ffae00>【轮换构建】</color>中构建获取<color=#FF3300>6星</color>角色的基础概率为<color=#ffae00>2%</color>，综合概率为<color=#ffae00>3%（含保底)</color>，<color=#FFCC00>5星</color>队员的基础概率为<color=#ffae00>8%</color>，<color=#6666FF>4星</color>队员的基础概率为<color=#ffae00>40%</color>，<color=#33CCFF>3星</color>队员的基础概率为<color=#ffae00>50%</color>。<color=#ffae00>10连构建必得5星或以上队员</color>。最多<color=#ffae00>50次构建</color>必定能获得保底<color=#ffae00>获取6星角色</color>。",["id"]="17140",["language3"]=[[<color=#ffae00>【定期構築】</color>の中で<color=#FF3300>★6</color>キャラの基本出現率は<color=#ffae00>2%</color>、総合確率は<color=#ffae00>3%（確定を含む)</color>。<color=#FFCC00>★5</color>キャラの基本確率は<color=#ffae00>8%</color>。<color=#6666FF>★4</color>キャラの基本出現率は<color=#ffae00>40%</color>。<color=#33CCFF>★3</color>キャラの基本出現率は<color=#ffae00>50%</color>。10連構築は<color=#FFCC00>★5</color>キャラが1体確定します。
<color=#ffae00>最大50回</color>構築で<color=#FF3300>★6</color>キャラが確定します。]],["language2"]="在所有<color=#ffae00>【輪換構建】</color>中構建獲取<color=#FF3300>6星</color>角色的基礎機率為<color=#ffae00>2%</color>，綜合機率為<color=#ffae00>3%（含保底)</color>，<color=#FFCC00>5星</color>隊員的基礎機率為<color=#ffae00>8%</color>，<color=#6666FF>4星</color>隊員的基礎機率為<color=#ffae00>40%</color>，<color=#33CCFF>3星</color>隊員的基礎機率為<color=#ffae00>50%</color>。<color=#ffae00>10連構建必得5星或以上隊員</color>。最多<color=#ffae00>50次構建</color>必定能獲得保底<color=#ffae00>獲取6星角色</color>。"}
